std::shared_ptr<const core::SelectionMask> EditorFrame::ActiveMask()const{return pixelMask_&&maskRevision_==revision_&&!pixelSelection_.IsRectEmpty()&&style_.tool!=core::Tool::Crop&&pixelSelection_.Size()==pixelMask_->bounds.Size()?pixelMask_:nullptr;}
void EditorFrame::CancelMask(){colorSeedPending_=false;maskGesture_=maskPending_=false;pixelMask_.reset();maskDraft_.points.clear();++maskEpoch_;if(GetCapture()==this&&!dragging_&&!objectGesture_&&!cropGesture_&&canvasHandle_<0)ReleaseCapture();}
void EditorFrame::MaskCommand(UINT id){if(id==PixelRect||id==PixelEllipse||id==PixelLasso){maskShape_=id==PixelRect?core::RegionShape::Rectangle:id==PixelEllipse?core::RegionShape::Ellipse:core::RegionShape::Freehand;ChangeTool(static_cast<int>(core::Tool::PixelSelect));}else{maskCombine_=id==PixelAdd?core::MaskCombine::Add:id==PixelSubtract?core::MaskCombine::Subtract:id==PixelIntersect?core::MaskCombine::Intersect:core::MaskCombine::Replace;ChangeTool(static_cast<int>(core::Tool::PixelSelect));}status_.SetWindowText(Tr(Text::PixelSelection));}
bool EditorFrame::MaskDown(CPoint p){if(style_.tool!=core::Tool::PixelSelect||maskPending_)return false;const auto mask=ActiveMask();const auto q=ImagePoint(p);if(maskCombine_==core::MaskCombine::Replace&&mask&&mask->Contains(q))return false;if(maskShape_==core::RegionShape::Rectangle&&maskCombine_==core::MaskCombine::Replace&&!mask)return false;maskGesture_=true;maskDraft_={CRect(q,q),maskShape_,{q}};maskDraftRevision_=revision_;start_=q;++maskEpoch_;SetCapture();return true;}
bool EditorFrame::MaskMove(CPoint p){if(!maskGesture_)return false;const auto q=ImagePoint(p);if(maskShape_==core::RegionShape::Freehand){if(maskDraft_.points.size()<4096&&(maskDraft_.points.back().x!=q.x||maskDraft_.points.back().y!=q.y))maskDraft_.points.push_back(q);LONG left=q.x,right=q.x,top=q.y,bottom=q.y;for(auto v:maskDraft_.points){left=std::min(left,v.x);right=std::max(right,v.x);top=std::min(top,v.y);bottom=std::max(bottom,v.y);}maskDraft_.rect={left,top,right,bottom};}else{CRect r(start_,q);r.NormalizeRect();maskDraft_.rect=r;}InvalidateRect(canvas_,FALSE);return true;}
bool EditorFrame::MaskUp(CPoint p){if(!maskGesture_)return false;MaskMove(p);maskGesture_=false;if(GetCapture()==this)ReleaseCapture();const CRect region=maskDraft_.rect;if(region.Width()<1||region.Height()<1||maskShape_==core::RegionShape::Freehand&&maskDraft_.points.size()<3)return true;maskPending_=true;EditorPolling(true);StartMask();return true;}
void EditorFrame::StartMask(){if(!maskPending_||job_.Busy())return;if(maskDraftRevision_!=revision_||style_.tool!=core::Tool::PixelSelect){maskPending_=false;return;}maskPending_=false;const auto before=ActiveMask();const auto region=pixelSelection_;const auto draft=maskDraft_;const auto combine=maskCombine_;const auto revision=revision_,epoch=maskEpoch_;const int width=document_.Width(),height=document_.Height();activeAction_=WorkMask;StartWork([before,region,draft,combine,revision,epoch,width,height]{WorkResult r;r.action=WorkMask;r.revision=revision;r.maskEpoch=epoch;auto source=before;if(!source&&!region.IsRectEmpty()&&combine!=core::MaskCombine::Replace)source=core::MakeSelectionMask(width,height,nullptr,{region},core::MaskCombine::Replace);r.mask=core::MakeSelectionMask(width,height,source.get(),draft,combine);return r;});status_.SetWindowText(Tr(Text::SelectionWorking));}
void EditorFrame::CompleteMask(WorkResult& r){if(r.revision!=revision_||r.maskEpoch!=maskEpoch_||style_.tool!=core::Tool::PixelSelect||maskGesture_||!r.mask)return;pixelMask_=std::move(r.mask);maskRevision_=revision_;pixelSelection_=pixelMask_->bounds;selected_=-1;selectedObjects_.clear();InvalidateRect(canvas_,FALSE);ViewStatus();}
bool EditorFrame::PaintMask(CDC& dc){if(style_.tool!=core::Tool::PixelSelect)return false;const auto mask=ActiveMask();if(!mask&&!maskGesture_){if(maskTint_&&!pixelSelection_.IsRectEmpty()){const auto r=ScreenRect(pixelSelection_);Gdiplus::Graphics graphics(dc);graphics.SetClip(Gdiplus::Rect(canvas_.left,canvas_.top,canvas_.Width(),canvas_.Height()));Gdiplus::SolidBrush brush(Gdiplus::Color(BYTE(maskTintAlpha_),GetRValue(maskTintColor_),GetGValue(maskTintColor_),GetBValue(maskTintColor_)));graphics.FillRectangle(&brush,r.left,r.top,r.Width(),r.Height());}return false;}CPen pen(PS_DOT,1,RGB(178,188,195));auto* previous=dc.SelectObject(&pen);auto* brush=dc.SelectStockObject(NULL_BRUSH);
    if(mask){const int dx=pixelSelection_.left-mask->bounds.left,dy=pixelSelection_.top-mask->bounds.top;if(maskTint_)PaintMaskTint(dc,*mask,dx,dy);const int top=ImagePoint(canvas_.TopLeft()).y-dy-2,bottom=ImagePoint(canvas_.BottomRight()).y-dy+2;auto begin=std::lower_bound(mask->outline.begin(),mask->outline.end(),top,[](const auto& line,int row){return line.y<row;});for(auto i=begin;i!=mask->outline.end()&&i->y<=bottom;++i){const auto a=ScreenRect({i->x1+dx,i->y+dy,i->x1+dx,i->y+dy}).TopLeft();const auto b=ScreenRect({i->x2+dx,i->y+dy+(i->vertical?1:0),i->x2+dx,i->y+dy+(i->vertical?1:0)}).TopLeft();dc.MoveTo(a);dc.LineTo(b);}}
    if(maskGesture_){auto rect=ScreenRect(maskDraft_.rect);if(maskShape_==core::RegionShape::Ellipse)dc.Ellipse(rect);else if(maskShape_==core::RegionShape::Freehand){std::vector<POINT> points;for(auto p:maskDraft_.points)points.push_back(ScreenRect({p.x,p.y,p.x,p.y}).TopLeft());if(points.size()>1)dc.Polyline(points.data(),static_cast<int>(points.size()));}else dc.Rectangle(rect);}dc.SelectObject(brush);dc.SelectObject(previous);return true;
}
